NodeEventMapping::NodeEventMapping():signal_(NodeEventSignal::COUNT),eventType_(EventType::NONE),severity_(EventSeverity::COUNT),enabled_(false),valid_(false){}NodeEventMapping NodeEventMapping::create(NodeEventSignal signal,EventType type,EventSeverity severity,bool enabled){NodeEventMapping r;if(!isValidNodeEventSignal(signal)||type==EventType::NONE||!isValidEventType(type)||!isValidEventSeverity(severity))return r;r.signal_=signal;r.eventType_=type;r.severity_=severity;r.enabled_=enabled;r.valid_=true;return r;}bool NodeEventMapping::isValid()const{return valid_&&isValidNodeEventSignal(signal_)&&eventType_!=EventType::NONE&&isValidEventType(eventType_)&&isValidEventSeverity(severity_);}NodeEventSignal NodeEventMapping::signal()const{return signal_;}EventType NodeEventMapping::eventType()const{return eventType_;}EventSeverity NodeEventMapping::severity()const{return severity_;}bool NodeEventMapping::enabled()const{return enabled_;}
